/**
 * DOMPurify offline standalone sanitizer for Trợ Lý AI.
 * Strict local HTML sanitization without external network/CDN dependencies.
 */
(function (global) {
    'use strict';

    const ALLOWED_TAGS = new Set([
        'a', 'b', 'blockquote', 'br', 'code', 'dd', 'div', 'dl', 'dt', 'em',
        'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'hr', 'i', 'li', 'ol', 'p', 'pre',
        'span', 'strong', 'sub', 'sup', 'table', 'tbody', 'td', 'th', 'thead', 'tr', 'ul'
    ]);

    const ALLOWED_ATTRS = new Set([
        'href', 'title', 'target', 'class', 'id', 'align', 'colspan', 'rowspan'
    ]);

    function sanitize(dirty) {
        if (!dirty || typeof dirty !== 'string') return '';

        // Tạo DOM parser cục bộ
        const parser = new DOMParser();
        const doc = parser.parseFromString(dirty, 'text/html');
        const body = doc.body;

        cleanNode(body);
        return body.innerHTML;
    }

    function cleanNode(node) {
        const children = Array.from(node.childNodes);
        for (const child of children) {
            if (child.nodeType === Node.ELEMENT_NODE) {
                const tagName = child.tagName.toLowerCase();

                // 1. Chặn thẳng các thẻ nguy hiểm (script, iframe, object, embed, style, img onerror)
                if (!ALLOWED_TAGS.has(tagName)) {
                    child.remove();
                    continue;
                }

                // 2. Lọc bỏ các thuộc tính không an toàn và các event handler on*
                const attrs = Array.from(child.attributes);
                for (const attr of attrs) {
                    const attrName = attr.name.toLowerCase();
                    const attrVal = attr.value;

                    if (!ALLOWED_ATTRS.has(attrName) || attrName.startsWith('on')) {
                        child.removeAttribute(attr.name);
                        continue;
                    }

                    // 3. Chặn javascript: trong href
                    if (attrName === 'href') {
                        const cleanVal = attrVal.trim().toLowerCase();
                        if (cleanVal.startsWith('javascript:') || cleanVal.startsWith('data:')) {
                            child.removeAttribute(attr.name);
                        } else {
                            // Đảm bảo mở tab mới an toàn
                            child.setAttribute('target', '_blank');
                            child.setAttribute('rel', 'noopener noreferrer');
                        }
                    }
                }

                // Đệ quy làm sạch các node con
                cleanNode(child);
            }
        }
    }

    const DOMPurify = {
        sanitize: sanitize,
        isSupported: true,
        version: '3.0.0-offline'
    };

    if (typeof module !== 'undefined' && module.exports) {
        module.exports = DOMPurify;
    } else {
        global.DOMPurify = DOMPurify;
    }
})(typeof window !== 'undefined' ? window : this);
